-- One opaque revision for the owner's two-generation backup. Only business
-- facts contribute: opening a session, polling, making a checkpoint or
-- downloading it must not displace the previous generation.
CREATE TABLE backup_business_state (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL);
INSERT INTO backup_business_state VALUES(1,1);
CREATE TRIGGER backup_library_i AFTER INSERT ON libraries BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_library_u AFTER UPDATE ON libraries WHEN OLD.data IS NOT NEW.data BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_library_d AFTER DELETE ON libraries BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_asset_i AFTER INSERT ON assets BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_asset_u AFTER UPDATE OF data ON assets WHEN OLD.data IS NOT NEW.data BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_asset_d AFTER DELETE ON assets BEGIN UPDATE backup_business_state SET revision=revision+1; END;
