CREATE TRIGGER backup_tag_i AFTER INSERT ON tags BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_tag_u AFTER UPDATE ON tags WHEN OLD.revision IS NOT NEW.revision OR OLD.deleted IS NOT NEW.deleted OR OLD.name IS NOT NEW.name BEGIN UPDATE backup_business_state SET revision=revision+1; END;
