CREATE TRIGGER backup_batch_i AFTER INSERT ON batches BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_batch_u AFTER UPDATE ON batches WHEN json_remove(OLD.data,'$.revision','$.updatedAt','$.backupState','$.cleanupState') IS NOT json_remove(NEW.data,'$.revision','$.updatedAt','$.backupState','$.cleanupState') BEGIN UPDATE backup_business_state SET revision=revision+1; END;
CREATE TRIGGER backup_batch_d AFTER DELETE ON batches BEGIN UPDATE backup_business_state SET revision=revision+1; END;
